import re


def next_version(current, commits):
    """The version after `current`, decided by the commit messages. See TASK.md."""
    # Parse and validate current version
    parts = current.split('.')
    if len(parts) != 3:
        raise ValueError("Invalid version format")

    # Validate each part is a non-negative integer without leading zeros
    try:
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])
    except ValueError:
        raise ValueError("Invalid version format")

    # Check for non-negative and no leading zeros
    if major < 0 or minor < 0 or patch < 0:
        raise ValueError("Invalid version format")

    for p in parts:
        if p != str(int(p)):
            raise ValueError("Invalid version format")

    # Determine the strongest change needed
    strongest_change = None  # None, 'fix', 'feature', 'breaking'

    for commit in commits:
        lines = commit.split('\n')
        if not lines:
            continue

        header = lines[0]

        # Parse header: type(scope)!: text or type!: text or type(scope): text or type: text
        # Pattern: lowercase letters, optionally (scope), optionally !, colon, space
        pattern = r'^([a-z]+)(?:\([^)]+\))?(!?):\s'
        match = re.match(pattern, header)

        if not match:
            continue  # Not a valid header

        # Extract the type
        type_part = match.group(1)
        is_breaking_in_header = match.group(2) == '!'

        # Check for BREAKING CHANGE in body
        is_breaking_in_body = False
        for line in lines[1:]:
            if line.startswith('BREAKING CHANGE: ') or line.startswith('BREAKING-CHANGE: '):
                is_breaking_in_body = True
                break

        is_breaking = is_breaking_in_header or is_breaking_in_body

        # Determine change type
        if is_breaking:
            change = 'breaking'
        elif type_part == 'feat':
            change = 'feature'
        elif type_part == 'fix':
            change = 'fix'
        else:
            # Other types don't count unless breaking
            change = None

        # Update strongest change (breaking > feature > fix)
        if change is not None:
            if strongest_change is None:
                strongest_change = change
            elif change == 'breaking':
                strongest_change = 'breaking'
            elif strongest_change != 'breaking' and change == 'feature':
                strongest_change = 'feature'

    # Apply version bump based on strongest change
    if strongest_change is None:
        return current

    if major >= 1:
        # From 1.0.0 on
        if strongest_change == 'breaking':
            return f"{major + 1}.0.0"
        elif strongest_change == 'feature':
            return f"{major}.{minor + 1}.0"
        elif strongest_change == 'fix':
            return f"{major}.{minor}.{patch + 1}"
    else:
        # Below 1.0.0 (MAJOR is 0)
        if strongest_change == 'breaking':
            return f"0.{minor + 1}.0"
        elif strongest_change == 'feature' or strongest_change == 'fix':
            return f"0.{minor}.{patch + 1}"
